using System; using System.Data; using System.Text;
public partial class MyBets : System.Web.UI.Page{public string betsHtml="";protected void Page_Load(object sender,EventArgs e){if(Session["user"]==null){Response.Redirect("Login.aspx");return;}int userId=Convert.ToInt32(Session["userId"]);string sql="SELECT Bets.BetId,Bets.BetDate,Bets.BetCoins,Bets.BetResult,C.ClubName,A.ClubName AS ClubA,B.ClubName AS ClubB FROM Bets INNER JOIN Games ON Bets.GameId=Games.GameId INNER JOIN Clubs C ON Bets.BetClubId=C.ClubId INNER JOIN Clubs A ON Games.ClubAId=A.ClubId INNER JOIN Clubs B ON Games.ClubBId=B.ClubId WHERE Bets.UserId="+userId+" ORDER BY Bets.BetDate DESC";DataTable dt=MyAdoHelper.ExecuteDataTable(sql);StringBuilder s=new StringBuilder("<table class='dataTable'><tr><th>מספר</th><th>משחק</th><th>קבוצה נבחרת</th><th>מטבעות</th><th>תאריך</th><th>תוצאה</th></tr>");for(int i=0;i<dt.Rows.Count;i++){int r=Convert.ToInt32(dt.Rows[i]["BetResult"]);string status=r==-1?"ממתין":(r==1?"נכון":"לא נכון");s.Append("<tr><td>"+dt.Rows[i]["BetId"]+"</td><td>"+dt.Rows[i]["ClubA"]+" נגד "+dt.Rows[i]["ClubB"]+"</td><td>"+dt.Rows[i]["ClubName"]+"</td><td>"+dt.Rows[i]["BetCoins"]+"</td><td>"+Convert.ToDateTime(dt.Rows[i]["BetDate"]).ToString("dd/MM/yyyy HH:mm")+"</td><td>"+status+"</td></tr>");}s.Append("</table>");betsHtml=s.ToString();}}